import { sql } from "drizzle-orm";
import {
  varchar,
  integer,
  jsonb,
  timestamp,
  pgTable,
} from "drizzle-orm/pg-core";
import { z } from "zod";

import { nanoid } from "@/lib/utils";
import { contacts } from "./contacts";

/**
 * Lead scores generated by AI
 * Stores individual dimension scores from the AI model
 * Total score is calculated on the frontend based on current weights
 */
export const leadScores = pgTable("lead_scores", {
  id: varchar("id", { length: 191 })
    .primaryKey()
    .$defaultFn(() => nanoid()),

  // Foreign key to contacts table
  contactId: varchar("contact_id", { length: 191 })
    .notNull()
    .unique() // One score per contact
    .references(() => contacts.id, { onDelete: "cascade" }),

  // AI-generated dimension scores (0-100)
  industryMatchScore: integer("industry_match_score").notNull(),
  companyMatchScore: integer("company_match_score").notNull(),
  positionMatchScore: integer("position_match_score").notNull(),
  seniorityMatchScore: integer("seniority_match_score").notNull(),
  dealSizeScore: integer("deal_size_score").notNull(),

  // Optional: AI reasoning for each dimension
  reasoning: jsonb("reasoning").$type<{
    industryMatch?: string;
    companyMatch?: string;
    positionMatch?: string;
    seniorityMatch?: string;
    dealSize?: string;
  }>(),

  // Metadata
  createdAt: timestamp("created_at")
    .notNull()
    .default(sql`now()`),
  updatedAt: timestamp("updated_at")
    .notNull()
    .default(sql`now()`),
});

// Schema for inserting scores (manually defined because createSelectSchema doesn't work with jsonb)
export const insertLeadScoreSchema = z.object({
  contactId: z.string().min(1, "Contact ID is required"),
  industryMatchScore: z.number().int().min(0).max(100),
  companyMatchScore: z.number().int().min(0).max(100),
  positionMatchScore: z.number().int().min(0).max(100),
  seniorityMatchScore: z.number().int().min(0).max(100),
  dealSizeScore: z.number().int().min(0).max(100),
  reasoning: z
    .object({
      industryMatch: z.string().optional(),
      companyMatch: z.string().optional(),
      positionMatch: z.string().optional(),
      seniorityMatch: z.string().optional(),
      dealSize: z.string().optional(),
    })
    .optional(),
});

export type LeadScore = typeof leadScores.$inferSelect;
export type NewLeadScoreParams = z.infer<typeof insertLeadScoreSchema>;
